3	module lab6_dbg_tb;
4	    reg clk, rst;
5	    RV32core core(
6	        .debug_en(1'b0), .debug_step(1'b0), .debug_addr(7'b0), .debug_data(),
7	        .wb_addr(), .wb_data(), .clk(clk), .rst(rst), .interrupter(1'b0)
8	    );
9	    initial begin clk = 0; rst = 1; #10 rst = 0; end
10	    always #1 clk = ~clk;
11	
12	    integer cycle = 0;
13	    integer e;
14	    always @(posedge clk) if (!rst) begin
15	        cycle = cycle + 1;
16	        if (cycle >= 4 && cycle <= 22) begin
17	            $write("cyc %0d: ISpc=%h en_FU=%b fu_busy=%b finish=%b done=%b cdb=%h:%h |",
18	                   cycle, core.PC_IS, core.FU_ALU_EN, core.rs_alu.fu_busy,
19	                   core.FU_ALU_finish, core.done_record, core.cdb_rs_num, core.cdb_data);
20	            for (e = 0; e < 3; e = e + 1)
21	                $write(" e%0d[B=%b Q1=%h Q2=%h V1=%h pc=%h disp=%b]", e,
22	                       core.rs_alu.entry[e][0], core.rs_alu.entry[e][15:8],
23	                       core.rs_alu.entry[e][23:16], core.rs_alu.entry[e][63:32],
24	                       core.rs_alu.entry[e][159:128], core.rs_alu.dispatched[e]);
25	            $display("");
26	        end
27	        if (cycle > 22) $finish;
28	    end
29	endmodule

